const buf = msg.payload;

const header = buf.readUInt8(0);
if (header == 0xef){
    const command = buf.readUInt16BE(1);
    // const mac = buf.slice(3, 9).toString('hex');
    const mac = buf.toString('hex', 3, 9);
    let length = buf.readUInt16BE(9);
    const data = buf.slice(11, 11+length);
    return {        
        payload: {
            header: header,
            command: command,
            mac:mac,
            length:length+0,
            data: data
        }
    };
}

const buf = msg.payload.data;
const length = msg.payload.length;
let index = 0;
let timestamp, fixMode, fixResult, lng, lat, ac, cid;
while (index < length) {
    const tag = buf.readUInt8(index);
    const segLens = buf.readUInt16BE(index + 1)
    index += 3;
    switch (tag) {
        // timestamp
        case 0x0:
            timestamp = buf.readUInt32BE(index);
            index += segLens;
            continue;

        // fix mode
        case 0x1:
            fixMode = buf.readUInt8(index);
            index += segLens;
            continue;

        // fix result
        case 0x2:
            fixResult = buf.readUInt8(index);
            index += segLens;
            continue;

        // lng,lat
        case 0x3:
            lng = buf.readInt32BE(index) * 0.0000001;
            lat = buf.readInt32BE(index + 4) * 0.0000001;
            index += segLens;
            continue;

        // lbs
        case 0x4:
            ac = buf.readUInt16BE(index);
            cid = buf.readUInt32BE(index + 2);
            index += segLens;
            continue;
    }
}

switch (fixMode) {
    case 0:
        return {
            payload: {
                mac: msg.payload.mac,
                mode: 'GPS',
                timestamp: timestamp,
                fixResult: fixResult,
                longitude: lng,
                latitude: lat
            }
        }
    case 1:
        return {
            payload: {
                mac: msg.payload.mac,
                mode: 'LBS',
                timestamp: timestamp,
                fixResult: fixResult,
                areaCode: ac,
                cellID: cid
            }
        }

}

const BEACON_TYPE = {
    0: "iBeacon",
    1: "Eddystone-UID",
    2: "Eddystone-URL",
    3: "Eddystone-TLM",
    4: "BXP-Device info",
    5: "BXP-ACC",
    6: "BXP-TH",
    7: "BXP-Button",
    8: "BXP-Tag",
    9: "PIR",
    10:"Nano Beacon",
    11: "Other type",
    12: "TOF"
};

const whitelist = {
    "c647b7b8e4d0": 1,
    "c2e170c50436": 1,
    "7c31faa3f6d9": 1,
};

const beacons = [];
const buf = msg.payload.data;
const length = msg.payload.length;

let index = 0;

let beaconType, beaconMac, beaconConnectable, timestamp, timezone, rssi, bleAdv, bleResp;

function resetRecord() {
    beaconType = undefined;
    beaconMac = undefined;
    beaconConnectable = undefined;
    timestamp = undefined;
    timezone = undefined;
    rssi = undefined;
    bleAdv = undefined;
    bleResp = undefined;
}

function pushRecord() {
    if (!beaconMac || !whitelist[beaconMac] ) return;

    beacons.push({
        macGateway: msg.payload.mac,
        macBeacon: beaconMac,
        beaconTypeCode: beaconType,
        beaconType: BEACON_TYPE[beaconType] || beaconType,
        beaconConnectable: beaconConnectable,
        timestamp: timestamp,
        timezone: timezone,
        rssi: rssi,
        bleAdv: bleAdv,
        bleResp: bleResp
    });
}

resetRecord();

while (index < length) {
    const tag = buf.readUInt8(index);
    const segLens = buf.readUInt16BE(index + 1);
    index += 3;

    if (index + segLens > length) break;

    switch (tag) {
        case 0x00: // start new record
            pushRecord();
            resetRecord();
            if (segLens >= 1) beaconType = buf.readUInt8(index);
            index += segLens;
            continue;

        case 0x01: // mac
            beaconMac = buf.toString("hex", index, index + segLens).toLowerCase();
            index += segLens;
            continue;

        case 0x02: // connectable
            if (segLens >= 1) beaconConnectable = buf.readUInt8(index);
            index += segLens;
            continue;

        case 0x03: // timestamp + timezone
            if (segLens >= 5) {
                timestamp = buf.readUInt32BE(index);
                timezone = buf.readUInt8(index + 4);
            }
            index += segLens;
            continue;

        case 0x04: // rssi
            if (segLens >= 1) rssi = buf.readInt8(index);
            index += segLens;
            continue;

        case 0x05: // adv raw
            bleAdv = buf.toString("hex", index, index + segLens).toLowerCase();
            index += segLens;
            continue;

        case 0x06: // resp raw
            bleResp = buf.toString("hex", index, index + segLens).toLowerCase();
            index += segLens;
            continue;

        default:

            index += segLens;
            continue;
    }
}

pushRecord();

msg.payload = beacons.filter(b => b.macBeacon && (b.bleAdv || b.bleResp));
return msg;

const p = msg.payload;
const adv = String(p.bleAdv || "").toLowerCase();
const resp = String(p.bleResp || "").toLowerCase();

p.frameClass = "UNKNOWN";
p.sensorType = "UNKNOWN";
p.sensorValues = {};


// -------------------------------------------------------------
// 2) H4 Pro (BXP‑TH) — Frame type 0x70
// -------------------------------------------------------------
if (adv.includes("abfe70")) {
    p.frameClass = "BXP-TH";
    p.sensorType = "H4_PRO";

    const idx = adv.indexOf("abfe70");
    const buf = Buffer.from(adv.slice(idx + 6), "hex");

    if (buf.length >= 8) {
        // ONLY temp, humidity, battery
        p.sensorValues['temperature'] = buf.readInt16BE(2) / 10;
        p.sensorValues['humidity'] = buf.readUInt16BE(4) / 10;
    }
}

// -------------------------------------------------------------
// 3) MK PIR Series (Company ID 0x0A62) → S03D
// -------------------------------------------------------------
else if (adv.includes("0a62")) {
    p.frameClass = "PIR";
    p.sensorType = "S03D";

    const idx = adv.indexOf("0a62");
    const buf = Buffer.from(adv.slice(idx + 4), "hex");

    if (buf.length >= 23) {
        const status = buf.readUInt8(2);
        p.sensorValues['doorOpen'] = (((status >> 3) & 0x01) === 1);
    }
}

// -------------------------------------------------------------
// 4) S05T (BXP_SENSOR_INFO 0x1601EA80)
// -------------------------------------------------------------
else if (adv.includes("1601ea80")) {
    const idx = adv.indexOf("1601ea80");
    const buf = Buffer.from(adv.slice(idx + 8), "hex");

    if (buf.length >= 17) {
        const status = buf.readUInt8(0);
        const doorOpen = (status & 0x01) === 1;
        const tempEquipped = ((status >> 3) & 0x01) === 1;
        const battRaw = buf.readUInt16BE(15);

        if (doorOpen) {
            // S03D mode inside S05T frame
            p.frameClass = "BXP_SENSOR_INFO";
            p.sensorType = "S03D";
            p.sensorValues['doorOpen'] = doorOpen;
        } else {

            p.frameClass = "BXP_SENSOR_INFO";
            p.sensorType = "S05T";
            p.sensorValues = {
                temperature: tempEquipped ? buf.readInt16BE(11) / 10 : null,
            };
        }
    }
}

// -------------------------------------------------------------
// 5) iBeacon / Eddystone
// -------------------------------------------------------------
else if (["ibeacon", "eddystone-uid", "eddystone-url", "eddystone-tlm"].includes(p.beaconType)) {
    p.sensorType = "N1";
    p.frameClass = p.beaconType;
    p.sensorValues = { frame: p.beaconType };
}

// -------------------------------------------------------------
// 6) Fallback
// -------------------------------------------------------------
else {
    // p.sensorValues = {
    //     beaconType: p.beaconType,
    //     beaconTypeCode: p.beaconTypeCode,
    //     rawAdv: p.bleAdv,
    //     rawResp: p.bleResp
    // };
    return null;
}

msg.payload = p;
return msg;

function mask_geolocation(lat, long) {
    const min = -0.000005;
    const max = 0.000005;

    return {
        latitude: lat + Math.random() * (max - min) + min,
        longitude: long + Math.random() * (max - min) + min
    };
}

// --- Input ---
const p = msg.payload;

if (!p.macBeacon) {
    node.warn("macBeacon missing");
    return null;
}

if (p.sensorType == 'S05T') {
    const masked = mask_geolocation(flow.get('latitude'), flow.get('longitude'));

    msg.method = "PUT";
    msg.url = `${flow.get('omlox_api_url')}/providers/${encodeURIComponent(p.macBeacon)}/location`;
    msg.headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "Authorization": "Bearer <token>"
    };
    const now = new Date().toISOString();

    msg.payload = {
        position: {
            type: "Point",
            coordinates: [masked.longitude, masked.latitude]
        },

        source: flow.get('omlox_zoneId'),
        provider_type: "ibeacon",
        provider_id: p.macBeacon,

        timestamp_generated: now,
        timestamp_sent: now,

        crs: "EPSG:4326",

        // Optional but lightweight defaults
        floor: 0,
        properties: {
            gatewayPos: {
                latitude: flow.get('latitude'),
                longitude: flow.get('longitude')
            }
        }
    };

    return msg;
}

return null;

if (!msg.payload.sensorValues) 
    return null;

var gatewaySensors = flow.get('gatewaySensors') ? flow.get('gatewaySensors') : {};
for (const [key, value] of Object.entries(msg.payload.sensorValues)) {
    gatewaySensors[key] = value;
}
flow.set('gatewaySensors', gatewaySensors)

msg.method = 'PUT';
msg.url = `${flow.get('omlox_api_url')}/providers/${msg.payload.macGateway}/sensors`
msg.payload = gatewaySensors;

return msg;
